CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('administrator','chief_officer','apparatus_officer','firefighter','maintenance_user');
CREATE TYPE inspection_status AS ENUM ('draft','submitted'); CREATE TYPE answer_status AS ENUM ('pass','fail','na','attention');
CREATE TYPE apparatus_status AS ENUM ('available','limited','out_of_service'); CREATE TYPE deficiency_status AS ENUM ('open','assigned','in_progress','completed','deferred');
CREATE TABLE stations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, address text, created_at timestamptz DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, display_name text NOT NULL, role user_role NOT NULL DEFAULT 'firefighter', station_id uuid REFERENCES stations, active boolean DEFAULT true, created_at timestamptz DEFAULT now());
CREATE TABLE apparatus_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE);
CREATE TABLE inspection_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, frequency text NOT NULL CHECK(frequency IN('daily','weekly','monthly','annual')), apparatus_type_id uuid REFERENCES apparatus_types, active boolean DEFAULT true, created_at timestamptz DEFAULT now());
CREATE TABLE apparatus(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), unit_number text NOT NULL UNIQUE, name text NOT NULL, station_id uuid NOT NULL REFERENCES stations, type_id uuid REFERENCES apparatus_types, vin text UNIQUE, mileage integer DEFAULT 0 CHECK(mileage>=0), fuel_level numeric(5,2) CHECK(fuel_level BETWEEN 0 AND 100), status apparatus_status NOT NULL DEFAULT 'available', in_service boolean NOT NULL DEFAULT true, checklist_id uuid REFERENCES inspection_templates, qr_token uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE equipment_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE);
CREATE TABLE equipment(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, category_id uuid REFERENCES equipment_categories, serial_number text UNIQUE, manufacturer text, model text, apparatus_id uuid REFERENCES apparatus, station_id uuid REFERENCES stations, required_quantity integer DEFAULT 1 CHECK(required_quantity > 0), inspection_frequency text CHECK(inspection_frequency IN('daily','weekly','monthly','annual')), expiration_date date, condition text NOT NULL DEFAULT 'good' CHECK(condition IN('good','attention','failed','out_of_service')), replacement_cost numeric(12,2), photo_url text, created_at timestamptz DEFAULT now(), CHECK(apparatus_id IS NOT NULL OR station_id IS NOT NULL));
CREATE TABLE inspection_questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_id uuid NOT NULL REFERENCES inspection_templates ON DELETE CASCADE, question text NOT NULL, section text, display_order integer NOT NULL, required boolean DEFAULT true, UNIQUE(template_id,display_order));
CREATE TABLE inspections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), apparatus_id uuid NOT NULL REFERENCES apparatus, template_id uuid NOT NULL REFERENCES inspection_templates, inspector_id uuid NOT NULL REFERENCES users, started_at timestamptz DEFAULT now(), submitted_at timestamptz, status inspection_status DEFAULT 'draft', signature_name text, notes text);
CREATE TABLE inspection_responses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), inspection_id uuid NOT NULL REFERENCES inspections ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES inspection_questions, response answer_status NOT NULL, note text, photo_url text, UNIQUE(inspection_id,question_id), CHECK(response NOT IN ('fail','attention') OR note IS NOT NULL));
CREATE TABLE deficiencies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), apparatus_id uuid REFERENCES apparatus, equipment_id uuid REFERENCES equipment, inspection_id uuid REFERENCES inspections, response_id uuid REFERENCES inspection_responses, title text NOT NULL, description text NOT NULL, severity text NOT NULL DEFAULT 'medium' CHECK(severity IN('low','medium','high','critical')), status deficiency_status NOT NULL DEFAULT 'open', assigned_to uuid REFERENCES users, due_date date, created_by uuid NOT NULL REFERENCES users, completed_at timestamptz, created_at timestamptz DEFAULT now(), CHECK(apparatus_id IS NOT NULL OR equipment_id IS NOT NULL));
CREATE TABLE repair_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), deficiency_id uuid NOT NULL REFERENCES deficiencies, performed_by uuid REFERENCES users, repair_notes text NOT NULL, parts text, cost numeric(12,2) DEFAULT 0, completed_at timestamptz, created_at timestamptz DEFAULT now());
CREATE TABLE attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_type text NOT NULL, entity_id uuid NOT NULL, file_name text NOT NULL, file_url text NOT NULL, uploaded_by uuid REFERENCES users, created_at timestamptz DEFAULT now());
CREATE TABLE audit_log(id bigserial PRIMARY KEY, actor_id uuid REFERENCES users, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, detail jsonb DEFAULT '{}', created_at timestamptz DEFAULT now());
CREATE INDEX ON deficiencies(status,due_date); CREATE INDEX ON inspections(apparatus_id,submitted_at); CREATE INDEX ON equipment(expiration_date);
ALTER TABLE stations ENABLE ROW LEVEL SECURITY; ALTER TABLE apparatus ENABLE ROW LEVEL SECURITY; ALTER TABLE equipment ENABLE ROW LEVEL SECURITY; ALTER TABLE inspections ENABLE ROW LEVEL SECURITY; ALTER TABLE deficiencies ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION current_app_role() RETURNS text LANGUAGE sql STABLE AS $$ SELECT current_setting('app.role',true) $$;
CREATE POLICY station_read ON stations FOR SELECT USING(current_app_role() IS NOT NULL);
CREATE POLICY apparatus_read ON apparatus FOR SELECT USING(current_app_role() IN ('administrator','chief_officer','maintenance_user') OR station_id::text=current_setting('app.station_id',true));
CREATE POLICY equipment_read ON equipment FOR SELECT USING(current_app_role() IN ('administrator','chief_officer','maintenance_user') OR station_id::text=current_setting('app.station_id',true) OR apparatus_id IN(SELECT id FROM apparatus WHERE station_id::text=current_setting('app.station_id',true)));
CREATE POLICY inspection_read ON inspections FOR SELECT USING(current_app_role() IN ('administrator','chief_officer','maintenance_user') OR inspector_id::text=current_setting('app.user_id',true) OR apparatus_id IN(SELECT id FROM apparatus WHERE station_id::text=current_setting('app.station_id',true)));
CREATE POLICY deficiency_read ON deficiencies FOR SELECT USING(current_app_role() IN ('administrator','chief_officer','maintenance_user') OR assigned_to::text=current_setting('app.user_id',true) OR apparatus_id IN(SELECT id FROM apparatus WHERE station_id::text=current_setting('app.station_id',true)));
CREATE POLICY apparatus_write ON apparatus FOR ALL USING(current_app_role() IN ('administrator','chief_officer','apparatus_officer')) WITH CHECK(current_app_role() IN ('administrator','chief_officer','apparatus_officer'));
CREATE POLICY equipment_write ON equipment FOR ALL USING(current_app_role() IN ('administrator','chief_officer','apparatus_officer','maintenance_user')) WITH CHECK(current_app_role() IN ('administrator','chief_officer','apparatus_officer','maintenance_user'));
CREATE POLICY inspection_write ON inspections FOR ALL USING(current_app_role() IS NOT NULL) WITH CHECK(current_app_role() IS NOT NULL);
CREATE POLICY deficiency_write ON deficiencies FOR ALL USING(current_app_role() IN ('administrator','chief_officer','apparatus_officer','maintenance_user')) WITH CHECK(current_app_role() IN ('administrator','chief_officer','apparatus_officer','maintenance_user'));
